const svg = d3.select("#bubble-chart");
const width = 650;
const height = 520;
svg.attr("width", width).attr("height", height);

const tooltip = d3.select("#tooltip");

function formatMarketCap(value) {
  if (value === null || value === undefined || isNaN(value)) return "N/A";
  if (value >= 1e12) return (value / 1e12).toFixed(2) + "T";
  if (value >= 1e9) return (value / 1e9).toFixed(2) + "B";
  if (value >= 1e6) return (value / 1e6).toFixed(2) + "M";
  return value.toString();
}

d3.csv("data/stock-descriptions.csv", d3.autoType).then(data => {
  // Clean data
  data.forEach(d => {
    d.marketCap = d.marketCap === null ? undefined : d.marketCap;
  });

  const sectors = Array.from(new Set(data.map(d => d.sector)));
  const color = d3.scaleOrdinal().domain(sectors).range(d3.schemeTableau10.concat(d3.schemeSet3));

  // Radius scale for market cap
  const caps = data.filter(d => d.marketCap).map(d => d.marketCap);
  const rScale = d3.scaleSqrt().domain([d3.min(caps), d3.max(caps)]).range([10, 45]);

  data.forEach(d => {
    d.radius = d.marketCap ? rScale(d.marketCap) : 14; // uniform for ETFs
  });

  // Cluster centers in grid
  const n = sectors.length;
  const cols = Math.ceil(Math.sqrt(n));
  const rows = Math.ceil(n / cols);
  const xSpacing = width / (cols + 1);
  const ySpacing = height / (rows + 1);
  const centers = {};
  sectors.forEach((s, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    centers[s] = { x: (col + 1) * xSpacing, y: (row + 1) * ySpacing };
  });

  // Nodes
  const nodes = svg.selectAll("g.node")
    .data(data)
    .enter()
    .append("g")
    .attr("class", "node");

  nodes.append("circle")
    .attr("r", d => d.radius)
    .attr("fill", d => color(d.sector))
    .attr("opacity", 0.85);

  nodes.append("text")
    .text(d => d.ticker)
    .attr("text-anchor", "middle")
    .attr("dy", ".35em")
    .style("font-size", d => Math.min(12, d.radius))
    .style("pointer-events", "none")
    .style("fill", "#fff");

  const simulation = d3.forceSimulation(data)
    .force("x", d3.forceX(d => centers[d.sector].x).strength(0.2))
    .force("y", d3.forceY(d => centers[d.sector].y).strength(0.2))
    .force("collide", d3.forceCollide(d => d.radius + 1))
    .force("center", d3.forceCenter(width / 2, height / 2));

  simulation.on("tick", () => {
    nodes.attr("transform", d => `translate(${d.x},${d.y})`);
  });

  // Tooltip for non-ETF (marketCap present)
  nodes.on("mouseover", (event, d) => {
      if (!d.marketCap) return;
      tooltip.style("opacity", 1)
        .html(`<strong>${d.ticker}</strong><br/>${d['full name']}<br/>${d.sector}`);
    })
    .on("mousemove", (event) => {
      tooltip.style("left", (event.pageX + 10) + "px")
             .style("top", (event.pageY + 10) + "px");
    })
    .on("mouseout", () => {
      tooltip.style("opacity", 0);
    });

  // Legend
  const legend = d3.select("#legend");
  const legendItems = legend.selectAll("div.legend-item")
    .data(sectors)
    .enter()
    .append("div")
    .attr("class", "legend-item");

  legendItems.append("div")
    .attr("class", "legend-color")
    .style("background", d => color(d));

  legendItems.append("span").text(d => d);

  // Table
  const tbody = d3.select("#stock-table tbody");
  const rowsSel = tbody.selectAll("tr")
    .data(data)
    .enter()
    .append("tr")
    .attr("data-ticker", d => d.ticker);

  rowsSel.append("td").text(d => d.ticker);
  rowsSel.append("td").text(d => d['full name']);
  rowsSel.append("td").text(d => d.sector);
  rowsSel.append("td").text(d => formatMarketCap(d.marketCap));

  // Selection handling
  function selectTicker(ticker) {
    nodes.selectAll("circle").classed("selected", d => d.ticker === ticker);
    rowsSel.classed("selected", d => d.ticker === ticker);
  }

  nodes.on("click", (event, d) => {
    selectTicker(d.ticker);
  });

  rowsSel.on("click", (event, d) => {
    selectTicker(d.ticker);
  });
});
